\title{The Limit Distribution of Descendants in Random $d$-DAGs}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We study the number of descendants of a founding vertex in the random recursive
directed acyclic graph (DAG) $G_n$ of out-degree $d \ge 2$, in which each vertex
$v > d$ attaches to $d$ distinct earlier vertices chosen uniformly at random. The
central object is the descendant count $|D_n|$, and the central phenomenon is that,
after rescaling by $n^{1/d}$, it converges in distribution to a Gamma law with
shape $d$ and rate $1$:
\[
\frac{|D_n|}{n^{1/d}} \xrightarrow{\;d\;} \Gam(d, 1).
\]
We isolate and rigorously establish the two analytic pillars of this statement.
First, we analyze the mean-growth product $P_n(a) = \prod_{k=1}^n (1 + a/k)$ that
governs the expected descendant count with $a = 1/d$: we prove its exact closed
form $P_n(a) = \Gamma(n+1+a)/(\Gamma(1+a)\,n!)$ and the scaling limit
$P_n(a)/n^a \to 1/\Gamma(1+a)$, pinning the normalization exponent to exactly
$1/d$. Second, we develop the Gamma$(d,1)$ target distribution: we verify that its
density integrates to one, compute its $p$-th moment $\Gamma(d+p)/\Gamma(d)$,
establish the moment recurrence $m_{p+1} = (d+p)m_p$, identify the integer moments
as rising factorials $\prod_{i<k}(d+i)$, and derive mean $= d$ and variance $= d$.
The boundary case $d = 1$ (the random recursive tree) is treated separately:
$P_n(1) = n+1$ exactly, giving linear descendant growth with exponent $1$.
\end{abstract}

\maketitle

\section{Introduction}

Growing random structures --- networks in which vertices arrive sequentially and
attach to existing vertices according to a fixed rule --- are a cornerstone of
modern applied probability. They model citation graphs, hyperlink structures,
biological lineages, package-dependency ecosystems, and the spread of information.
A recurring theme is \emph{universality}: microscopically simple attachment rules
generate macroscopically robust limit laws.

Consider the \emph{random recursive $d$-DAG} $G_n$ on vertex set $\{1, \dots, n\}$
with out-degree $d \ge 2$: each vertex $v > d$ selects $d$ distinct earlier
vertices uniformly at random and directs an edge to each. Since edges always point
toward smaller labels, the graph is acyclic. Fixing a founding vertex, the
\emph{descendant set} $D_n$ consists of all vertices whose ancestry traces back to
the founder, and $|D_n|$ is its cardinality.

The governing result (Janson, 2023) states that
\[
\frac{|D_n|}{n^{1/d}} \xrightarrow{\;d\;} \Gam(d, 1), \qquad n \to \infty,
\]
where $\Gam(d,1)$ is the Gamma distribution with shape $d$ and rate $1$. Two
ingredients underlie any proof: the correct normalizing sequence (here $n^{1/d}$)
and a characterization of the limit strong enough to identify it uniquely (here,
its moments). This paper establishes both, self-containedly.

\section{Definitions and preliminaries}

Throughout, $\Gamma$ denotes the Euler Gamma function,
\[
\Gamma(s) = \int_0^\infty e^{-x}\, x^{s-1}\, dx \qquad (s > 0),
\]
which satisfies $\Gamma(s+1) = s\,\Gamma(s)$ and interpolates the factorial:
$\Gamma(m+1) = m!$ for $m \in \N$. We write $x^a = \exp(a \ln x)$ for the real
power ($x > 0$).

\begin{definition}[Mean-growth product]
For $a \in \R$ and $n \in \N$,
\[
P_n(a) = \prod_{k=1}^{n}\left(1 + \frac{a}{k}\right),
\]
with the empty-product convention $P_0(a) = 1$.
\end{definition}

With $a = 1/d$ this product captures the expected size of the descendant set: each
new vertex contributes a factor $1 + a/k$ to the running expectation.

\begin{definition}[Gamma$(d,1)$ density]
For shape $d > 0$, the Gamma$(d,1)$ density on $(0,\infty)$ is
$f_d(x) = e^{-x}\, x^{\,d-1}/\Gamma(d)$.
\end{definition}

\begin{definition}[Gamma moment]
For $d > 0$ and $p \ge 0$, the $p$-th moment is $m_d(p) = \Gamma(d+p)/\Gamma(d)$.
\end{definition}

\section{The mean-growth product and the scaling exponent}

\begin{lemma}[Recurrence]
For all $a \in \R$ and $n \in \N$,
$P_{n+1}(a) = P_n(a)\,\bigl(1 + a/(n+1)\bigr)$.
\end{lemma}

\begin{proof}
Peel off the top factor $k = n+1$ from the product over $k \in \{1,\dots,n+1\}$.
\end{proof}

\begin{theorem}[Exact closed form]
For $a \ge 0$ and $n \in \N$,
\[
P_n(a) = \frac{\Gamma(n+1+a)}{\Gamma(1+a)\, n!}.
\]
\end{theorem}

\begin{proof}
Induct on $n$. For $n = 0$ both sides equal $1$. Assuming the identity for $n$, the
recurrence gives
$P_{n+1}(a) = \frac{\Gamma(n+1+a)}{\Gamma(1+a)\,n!}\cdot\frac{n+1+a}{n+1}$.
Using $\Gamma(n+2+a) = (n+1+a)\Gamma(n+1+a)$ and $(n+1)! = (n+1)\,n!$, this equals
$\Gamma(n+2+a)/(\Gamma(1+a)\,(n+1)!)$.
\end{proof}

Recall Euler's approximating sequence
$\gamma_a(n) = n^a\, n! / \prod_{j=0}^{n}(a+j)$, with $\gamma_a(n) \to \Gamma(a)$
for $a > 0$.

\begin{lemma}[Link to the Gamma sequence]
For $a > 0$ and $n \ge 1$, $P_n(a) = n^a/(a\,\gamma_a(n))$.
\end{lemma}

\begin{proof}
Writing $1 + a/k = (a+k)/k$ gives $P_n(a) = \bigl(\prod_{k=1}^n (a+k)\bigr)/n!$.
Since $\prod_{j=0}^{n}(a+j) = a\prod_{k=1}^{n}(a+k)$, we get
$\prod_{k=1}^n (a+k) = \tfrac1a\, n^a n!/\gamma_a(n)$; divide by $n!$.
\end{proof}

\begin{theorem}[Scaling limit]
For $a > 0$, $\; P_n(a)/n^{a} \to 1/\Gamma(1+a)$ as $n \to \infty$.
\end{theorem}

\begin{proof}
By the previous lemma $P_n(a)/n^a = 1/(a\,\gamma_a(n)) \to 1/(a\,\Gamma(a))$, and
$a\,\Gamma(a) = \Gamma(a+1) = \Gamma(1+a)$.
\end{proof}

\begin{corollary}[$d$-DAG normalization]
For $d \ge 1$, with $a = 1/d$,
$\; P_n(1/d)/n^{1/d} \to 1/\Gamma(1 + 1/d)$.
\end{corollary}

This fixes the normalization exponent at exactly $1/d$ and explains why descendant
growth is sublinear for $d \ge 2$.

\section{The Gamma target distribution and its moments}

\begin{theorem}[Normalization]
For $d > 0$, $\int_0^\infty f_d(x)\,dx = 1$.
\end{theorem}

\begin{proof}
$\int_0^\infty f_d(x)\,dx = \frac{1}{\Gamma(d)}\int_0^\infty x^{d-1}e^{-x}\,dx =
\Gamma(d)/\Gamma(d) = 1$, using the integral definition of $\Gamma$. Nonnegativity
of $f_d$ on $(0,\infty)$ follows since each factor is nonnegative for $d > 0$.
\end{proof}

\begin{theorem}[Moment formula]
For $d > 0$ and $p \ge 0$,
$\int_0^\infty x^p f_d(x)\,dx = \Gamma(d+p)/\Gamma(d) = m_d(p)$.
\end{theorem}

\begin{proof}
$\int_0^\infty x^p \frac{e^{-x}x^{d-1}}{\Gamma(d)}\,dx =
\frac{1}{\Gamma(d)}\int_0^\infty e^{-x} x^{(d+p)-1}\,dx = \Gamma(d+p)/\Gamma(d)$,
valid since $d + p > 0$.
\end{proof}

\begin{corollary}[Zeroth moment]
$m_d(0) = \Gamma(d)/\Gamma(d) = 1$.
\end{corollary}

\begin{theorem}[Moment recurrence]
For $d > 0$ and $p \ge 0$, $\; m_d(p+1) = (d+p)\,m_d(p)$.
\end{theorem}

\begin{proof}
$m_d(p+1) = \Gamma(d+p+1)/\Gamma(d) = (d+p)\Gamma(d+p)/\Gamma(d) = (d+p)m_d(p)$.
\end{proof}

\begin{theorem}[Integer moments are rising factorials]
For $d > 0$ and $k \in \N$, $\; m_d(k) = \prod_{i=0}^{k-1}(d+i)$.
\end{theorem}

\begin{proof}
Induct on $k$. For $k=0$ the empty product is $1 = m_d(0)$. The step uses the
recurrence: $m_d(k+1) = (d+k)m_d(k) = (d+k)\prod_{i<k}(d+i) = \prod_{i<k+1}(d+i)$.
\end{proof}

\begin{corollary}[Mean, second moment, variance]
For $d > 0$: $\; m_d(1) = d$, $\; m_d(2) = d(d+1)$, and
$m_d(2) - m_d(1)^2 = d$.
\end{corollary}

Thus the Gamma$(d,1)$ law has mean and variance both equal to $d$.

\section{The boundary case: random recursive trees ($d=1$)}

\begin{theorem}[Exact tree product]
For all $n \in \N$, $\; P_n(1) = \prod_{k=1}^{n}(1 + 1/k) = n+1$.
\end{theorem}

\begin{proof}
The product telescopes: $\prod_{k=1}^n \tfrac{k+1}{k} = (n+1)/1$. Alternatively,
induct with the recurrence: $P_{n+1}(1) = (n+1)(1 + 1/(n+1)) = n+2$.
\end{proof}

\begin{theorem}[Linear scaling]
$P_n(1)/n = (n+1)/n \to 1$ as $n \to \infty$.
\end{theorem}

The scaling exponent is thus $1$, the value of $1/d$ at $d = 1$, consistent with
the general corollary since $1/\Gamma(2) = 1$.

\section{Assembling the limit law via the method of moments}

The two developments combine as follows.

\begin{enumerate}
\item \textbf{Scaling.} The corollary fixes the normalization:
$\E|D_n| \sim n^{1/d}/\Gamma(1+1/d)$, so $|D_n|/n^{1/d}$ is of order one.
\item \textbf{Moment convergence.} One shows for each $k$,
$\E[(|D_n|/n^{1/d})^k] \to \prod_{i=0}^{k-1}(d+i) = \Gamma(d+k)/\Gamma(d)$,
the integer Gamma moment. The recurrence $m_{p+1}=(d+p)m_p$ is exactly the relation
the asymptotic factorial moments of $|D_n|$ satisfy.
\item \textbf{Moment determinacy.} The Gamma law is determined by its moments
(Carleman's condition holds; equivalently its MGF is finite near the origin), so
moment convergence upgrades to convergence in distribution.
\end{enumerate}

\section{Applications and future work}

The random recursive $d$-DAG models citation networks, software-dependency graphs,
and genealogical branching; $|D_n|$ measures the downstream influence of an early
entity, growing like $n^{1/d}$ with Gamma-distributed fluctuations. Both the growth
rate ($1/d$) and the fluctuation shape ($d$) are controlled by the out-degree.

Future work includes: defining $G_n$ as a probability measure and connecting
$\E|D_n|$ to $P_n(1/d)$; proving discrete moment convergence; formalizing a
moment-determinacy criterion; the fluctuation law for $d = 1$; and the second-order
expansion $P_n(a) = \frac{n^a}{\Gamma(1+a)}(1 + O(1/n))$.

