"""Scaling limit  P_n(1/d) / n^{1/d} -> 1/Gamma(1 + 1/d).

Confirms that the descendant-count normalization exponent is exactly 1/d and
that the multiplicative constant is 1/Gamma(1 + 1/d).
"""

from __future__ import annotations

import math


def desc_product(a: float, n: int) -> float:
    result = 1.0
    for k in range(1, n + 1):
        result *= 1.0 + a / k
    return result


def scaling_ratio(a: float, n: int) -> float:
    """P_n(a) / n^a."""
    return desc_product(a, n) / (n ** a)


def main() -> None:
    for d in (2, 3, 5):
        a = 1.0 / d
        target = 1.0 / math.gamma(1 + a)
        print(f"d = {d}: target 1/Gamma(1 + 1/d) = {target:.10f}")
        print(f"  {'n':>8} {'P_n(a)/n^a':>18} {'|error|':>12}")
        for n in (10, 100, 1000, 10000, 100000):
            r = scaling_ratio(a, n)
            print(f"  {n:>8} {r:>18.10f} {abs(r - target):>12.2e}")
        print()


if __name__ == "__main__":
    main()

